import{_ as t,o as n,c as s,aa as e,j as a}from"./chunks/framework.BAs_AphD.js";const i="/buildary-help-preview/academy/img/pocasi/08.webp",r="/buildary-help-preview/academy/img/osoby-mechanizmy/05.webp",l="/buildary-help-preview/academy/img/osoby-mechanizmy/12.webp",h=JSON.parse('{"title":"Počasí, osoby, stroje a materiály","description":"","frontmatter":{"title":"Počasí, osoby, stroje a materiály","wiki":"cs:diary:dailyentriespersons"},"headers":[],"relativePath":"diary/dailyentriespersons.md","filePath":"diary/dailyentriespersons.md","lastUpdated":1794209661000}'),d={name:"diary/dailyentriespersons.md"};function p(m,o,c,y,u,k){return n(),s("div",null,[...o[0]||(o[0]=[e('<h1 id="pocasi-osoby-stroje-a-materialy" tabindex="-1">Počasí, osoby, stroje a materiály <a class="header-anchor" href="#pocasi-osoby-stroje-a-materialy" aria-label="Permalink to &quot;Počasí, osoby, stroje a materiály&quot;">​</a></h1><p>Čtyři sekce dne zachycují podmínky na stavbě: počasí, lidi, stroje a dodaný materiál. Počasí načtete jedním tlačítkem, osoby, mechanizmy a materiály zapisujete do tabulek – opakující se údaje vám aplikace nabídne z dřívějších záznamů.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/pocasi">Zapsat počasí</a> a <a href="/buildary-help-preview/akademie/osoby-mechanizmy">Zapsat osoby, stroje a materiál</a> v Akademii.</p><h2 id="pocasi" tabindex="-1">Počasí <a class="header-anchor" href="#pocasi" aria-label="Permalink to &quot;Počasí&quot;">​</a></h2>',4),a("div",{class:"video"},[a("iframe",{src:"https://www.youtube-nocookie.com/embed/GnwzfqcfyXk",title:"Video: Počasí",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),e('<p>Klikněte na <strong>Načíst počasí</strong> a tabulka se vyplní: počasí, teplota, srážky, rychlost a směr větru a vlhkost. Údaje se načítají podle GPS souřadnic stavby – bez nich počasí načíst nejde. Souřadnice stavby zadáte značkou v mapě při zakládání stavby, viz <a href="/buildary-help-preview/diary/projectsetup#umisteni">Založit stavbu – Umístění</a>.</p><figure class="shot" style="--w:760px;"><img src="'+i+'" alt="Sekce Počasí s načtenými hodnotami pro 6:00, 12:00 a 18:00 a poznámkou" loading="lazy"></figure><ul><li><strong>Kdy načíst</strong>: kdykoli během dne i později. Server použije naměřené hodnoty z meteorologických stanic, a pokud je ještě nemá, předpověď.</li><li><strong>Hodiny</strong>: počasí se zapisuje pro nastavené hodiny dne, standardně 6:00, 12:00 a 18:00. Hodiny a zobrazená pole mění administrátor deníku v <a href="/buildary-help-preview/diary/diarysettings">Nastavení deníku</a> na záložce <strong>Počasí</strong>.</li><li><strong>Úprava</strong>: načtenou hodnotu opravíte ikonou tužky na konci řádku. V okně <strong>Počasí</strong> přepište hodnoty podle skutečnosti a klikněte na <strong>Uložit</strong>.</li><li><strong>Poznámka</strong>: tlačítkem <strong>Přidat poznámku</strong> připíšete k počasí text, třeba „Ranní mlha do 8:00“. Text můžete i nadiktovat tlačítkem <strong>Nadiktovat</strong>. Uloženou poznámku změníte tlačítkem <strong>Upravit</strong>.</li></ul><p>Počasí se při <a href="/buildary-help-preview/diary/copydailyentries">kopírování dne</a> nekopíruje – pro nový den se vždy načte znovu.</p><p>Teplotu můžete načítat i z digitálního čidla Siotech umístěného na stavbě. Taková teplota pak nejde ručně upravit – viz <a href="/buildary-help-preview/diary/sensors">Čidla a odkaz na stavbu</a>.</p><h2 id="osoby-na-stavenisti" tabindex="-1">Osoby na staveništi <a class="header-anchor" href="#osoby-na-stavenisti" aria-label="Permalink to &quot;Osoby na staveništi&quot;">​</a></h2>',6),a("div",{class:"video"},[a("iframe",{src:"https://www.youtube-nocookie.com/embed/i1anbZAi1xA",title:"Video: Osoby, mechanizmy a materiály",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),e('<p>V sekci zapisujete všechny, kdo ten den na stavbě pracovali. Vyhláška č. 131/2024 Sb. (příloha č. 12) počítá se jmenovitým seznamem. Jestli budete osoby zapisovat jmenovitě, nebo třeba po partách, je na vás.</p><p>Nový záznam přidáte tlačítkem <strong>Přidat záznam</strong>. V okně <strong>Přidat osobu</strong> vyplníte:</p><ul><li><strong>Příjmení a jméno</strong> – povinný údaj. Může jít i o vedoucího party.</li><li><strong>Název profese</strong> a <strong>Název dodavatele</strong>.</li><li><strong>Počet osob</strong> a <strong>Počet hodin</strong>. Počet hodin se předvyplní podle pracovní doby.</li></ul><figure class="shot" style="--w:640px;"><img src="'+r+'" alt="Okno Přidat osobu s poli Příjmení a jméno, Název profese a Název dodavatele" loading="lazy"></figure><p><strong>Uložit a nový</strong> záznam uloží a hned otevře prázdný formulář pro další osobu. <strong>Uložit</strong> záznam uloží a okno zavře.</p><h3 id="nabidka-drive-zapsanych-udaju" tabindex="-1">Nabídka dříve zapsaných údajů <a class="header-anchor" href="#nabidka-drive-zapsanych-udaju" aria-label="Permalink to &quot;Nabídka dříve zapsaných údajů&quot;">​</a></h3><p>Aplikace si zapsané údaje pamatuje. Když začnete psát jméno, nabídne shodné dříve uložené záznamy. Po výběru se předvyplní i ostatní pole a můžete je upravit. Celý seznam uložených položek otevřete šipkou v poli.</p><p>Seznamy osob, mechanizmů a materiálů můžete připravit dopředu, ručně nebo importem z XLS – viz <a href="/buildary-help-preview/diary/codelists">Číselníky deníku</a>.</p><h3 id="poznamka-a-pracovni-doba" tabindex="-1">Poznámka a pracovní doba <a class="header-anchor" href="#poznamka-a-pracovni-doba" aria-label="Permalink to &quot;Poznámka a pracovní doba&quot;">​</a></h3><p>Tlačítkem <strong>Přidat poznámku</strong> připíšete k sekci text. Poznámka se ukládá samostatným tlačítkem. Do poznámky k osobám se může předvyplnit pracovní doba – nastavuje se v <a href="/buildary-help-preview/diary/diarysettings">Nastavení deníku</a> v poli <strong>Pracovní doba</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Docházkový systém</p><p>Osoby na staveništi mohou do deníku přicházet z docházkového systému na stavbě. Podporovaná napojení popisuje <a href="/buildary-help-preview/diary/attendance_system">Docházkový systém</a>.</p></div><h2 id="mechanizmy" tabindex="-1">Mechanizmy <a class="header-anchor" href="#mechanizmy" aria-label="Permalink to &quot;Mechanizmy&quot;">​</a></h2><p>Sekce <strong>Mechanizmy</strong> funguje stejně jako osoby. V okně záznamu vyplníte název prostředku, dodavatele, posádku, počet strojů a počet hodin.</p><h2 id="materialy-vyrobky-a-technologicke-dodavky" tabindex="-1">Materiály, výrobky a technologické dodávky <a class="header-anchor" href="#materialy-vyrobky-a-technologicke-dodavky" aria-label="Permalink to &quot;Materiály, výrobky a technologické dodávky&quot;">​</a></h2><p>Do sekce zapisujete dodaný materiál. Okno <strong>Přidat materiály, výrobky a technologické dodávky</strong> má pole <strong>Název materiálu</strong>, <strong>Název dodavatele</strong>, <strong>Vlastník</strong>, <strong>Číslo dodacího listu</strong>, <strong>Množství</strong> a <strong>Měrná jednotka</strong>.</p><figure class="shot" style="--w:640px;"><img src="'+l+'" alt="Okno Přidat materiály, výrobky a technologické dodávky s číslem dodacího listu" loading="lazy"></figure><p>Zapisujte i číslo dodacího listu – dodávku pak snadno dohledáte.</p><h2 id="co-maji-sekce-spolecne" tabindex="-1">Co mají sekce společné <a class="header-anchor" href="#co-maji-sekce-spolecne" aria-label="Permalink to &quot;Co mají sekce společné&quot;">​</a></h2><ul><li>Která pole se v sekci zobrazí a která jsou povinná, určuje <a href="/buildary-help-preview/diary/diarysettings">Nastavení deníku</a>.</li><li>Záznamy z jiného dne převezmete tlačítkem <strong>Kopírovat záznamy</strong> – viz <a href="/buildary-help-preview/diary/copydailyentries">Kopírovat záznamy</a>.</li><li>Záznam upravíte ikonou tužky a smažete ikonou koše na jeho řádku. Měnit a mazat můžete jen své záznamy a jen do uzamčení dne.</li></ul>',19)])])}const b=t(d,[["render",p]]);export{h as __pageData,b as default};
